96	/// Accounting for the `smart_case` config knob, return true if and only if
97	/// this pattern should be matched case insensitively.
98	fn is_case_insensitive(&self, analysis: &AstAnalysis) -> bool {
99	if self.case_insensitive {
100	return true;
101	}
102	if !self.case_smart {
103	return false;
104	}
105	analysis.any_literal() && !analysis.any_uppercase()
