113	/// are enabled, since if multi-line can impact the match semantics of a
114	/// regex, then it is by definition not a simple alternation of literals.
115	pub fn can_plain_aho_corasick(&self) -> bool {
116	!self.word && !self.case_insensitive && !self.case_smart
