163	    fn build_conflict_err(&self, name: &Id, matcher: &ArgMatcher) -> ClapResult<()> {
164	        debug!("Validator::build_conflict_err: name={:?}", name);
165	        let usg = Usage::new(self.p).create_usage_with_title(&[]);
166	        if let Some(other_arg) = self.p.app.find(name) {
167	            for k in matcher.arg_names() {
168	                if let Some(a) = self.p.app.find(k) {
169	                    if let Some(ref v) = a.blacklist {
170	                        if v.contains(&name) {
171	                            return Err(Error::argument_conflict(
172	                                a,
173	                                Some(other_arg.to_string()),
174	                                &*usg,
175	                                self.p.app.color(),
176	                            )?);
177	                        }
178	                    }
179	                }
180	            }
181	        } else if let Some(g) = self.p.app.groups.iter().find(|x| x.id == *name) {
182	            let args_in_group = self.p.app.unroll_args_in_group(&g.id);
183	            let first = matcher
184	                .arg_names()
185	                .find(|x| args_in_group.contains(x))
186	                .expect(INTERNAL_ERROR_MSG);
187	            let c_with = matcher
188	                .arg_names()
189	                .find(|x| x != &first && args_in_group.contains(x))
190	                .map(|x| self.p.app[x].to_string());
191	            debug!("Validator::build_conflict_err: c_with={:?}:group", c_with);
192	            return Err(Error::argument_conflict(
193	                &self.p.app[first],
194	                c_with,
195	                &*usg,
196	                self.p.app.color(),
197	            )?);
198	        }
199	
200	        panic!(INTERNAL_ERROR_MSG);
201	    }
