164	pub fn check_call(working_set: &mut StateWorkingSet, command: Span, sig: &Signature, call: &Call) {
165	    // Allow the call to pass if they pass in the help flag
166	    if call.named_iter().any(|(n, _, _)| n.item == "help") {
167	        return;
168	    }
169	
170	    if call.positional_len() < sig.required_positional.len() {
171	        // Comparing the types of all signature positional arguments against the parsed
172	        // expressions found in the call. If one type is not found then it could be assumed
173	        // that that positional argument is missing from the parsed call
174	        for argument in &sig.required_positional {
175	            let found = call.positional_iter().fold(false, |ac, expr| {
176	                if argument.shape.to_type() == expr.ty || argument.shape == SyntaxShape::Any {
177	                    true
178	                } else {
179	                    ac
180	                }
181	            });
182	            if !found {
183	                if let Some(last) = call.positional_iter().last() {
184	                    working_set.error(ParseError::MissingPositional(
185	                        argument.name.clone(),
186	                        Span::new(last.span.end, last.span.end),
187	                        sig.call_signature(),
188	                    ));
189	                    return;
190	                } else {
191	                    working_set.error(ParseError::MissingPositional(
192	                        argument.name.clone(),
193	                        Span::new(command.end, command.end),
194	                        sig.call_signature(),
195	                    ));
196	                    return;
197	                }
198	            }
199	        }
200	
201	        let missing = &sig.required_positional[call.positional_len()];
202	        if let Some(last) = call.positional_iter().last() {
203	            working_set.error(ParseError::MissingPositional(
204	                missing.name.clone(),
205	                Span::new(last.span.end, last.span.end),
206	                sig.call_signature(),
207	            ))
208	        } else {
209	            working_set.error(ParseError::MissingPositional(
210	                missing.name.clone(),
211	                Span::new(command.end, command.end),
212	                sig.call_signature(),
213	            ))
214	        }
215	    } else {
216	        for req_flag in sig.named.iter().filter(|x| x.required) {
217	            if call.named_iter().all(|(n, _, _)| n.item != req_flag.long) {
218	                working_set.error(ParseError::MissingRequiredFlag(
219	                    req_flag.long.clone(),
220	                    command,
221	                ));
222	            }
223	        }
224	    }
225	}
