295	pub fn parse_external_call(
296	    working_set: &mut StateWorkingSet,
297	    spans: &[Span],
298	    is_subexpression: bool,
299	) -> Expression {
300	    trace!("parse external");
301	
302	    let mut args = vec![];
303	
304	    let head_contents = working_set.get_span_contents(spans[0]);
305	
306	    let head_span = if head_contents.starts_with(b"^") {
307	        Span::new(spans[0].start + 1, spans[0].end)
308	    } else {
309	        spans[0]
310	    };
311	
312	    let head_contents = working_set.get_span_contents(head_span).to_vec();
313	
314	    let head = if head_contents.starts_with(b"$") || head_contents.starts_with(b"(") {
315	        // the expression is inside external_call, so it's a subexpression
316	        let arg = parse_expression(working_set, &[head_span], true);
317	        Box::new(arg)
318	    } else {
319	        let (contents, err) = unescape_unquote_string(&head_contents, head_span);
320	        if let Some(err) = err {
321	            working_set.error(err)
322	        }
323	
324	        Box::new(Expression {
325	            expr: Expr::String(contents),
326	            span: head_span,
327	            ty: Type::String,
328	            custom_completion: None,
329	        })
330	    };
331	
332	    for span in &spans[1..] {
333	        let arg = parse_external_arg(working_set, *span);
334	        args.push(arg);
335	    }
336	
337	    Expression {
338	        expr: Expr::ExternalCall(head, args, is_subexpression),
339	        span: span(spans),
340	        ty: Type::Any,
341	        custom_completion: None,
342	    }
343	}
