122	fn parse_collection_shape(
123	working_set: &mut StateWorkingSet,
124	bytes: &[u8],
125	span: Span,
126	use_loc: ShapeDescriptorUse,
127	) -> SyntaxShape {
128	assert!(bytes.starts_with(b"record") || bytes.starts_with(b"table"));
129	let is_table = bytes.starts_with(b"table");
130	
131	let name = if is_table { "table" } else { "record" };
132	let prefix = (if is_table { "table<" } else { "record<" }).as_bytes();
133	let prefix_len = prefix.len();
134	let mk_shape = |ty| -> SyntaxShape {
135	if is_table {
136	SyntaxShape::Table(ty)
137	} else {
138	SyntaxShape::Record(ty)
139	}
140	};
141	
142	if bytes == name.as_bytes() {
143	mk_shape(vec![])
144	} else if bytes.starts_with(prefix) {
145	let Some(inner_span) = prepare_inner_span(working_set, bytes, span, prefix_len) else {
146	return SyntaxShape::Any;
147	};
148	
149	// record<> or table<>
150	if inner_span.end - inner_span.start == 0 {
151	return mk_shape(vec![]);
152	}
153	let source = working_set.get_span_contents(inner_span);
154	let (tokens, err) = lex_signature(
155	source,
156	inner_span.start,
157	&[b'\n', b'\r'],
158	&[b':', b','],
159	true,
160	);
161	
162	if let Some(err) = err {
163	working_set.error(err);
164	// lexer errors cause issues with span overflows
165	return mk_shape(vec![]);
166	}
167	
168	let mut sig = vec![];
169	let mut idx = 0;
170	
171	let key_error = |span| {
172	ParseError::LabeledError(
173	format!("`{name}` type annotations key not string"),
174	"must be a string".into(),
175	span,
176	)
177	};
178	
179	while idx < tokens.len() {
180	let TokenContents::Item = tokens[idx].contents else {
181	working_set.error(key_error(tokens[idx].span));
182	return mk_shape(vec![]);
183	};
184	
185	let key_bytes = working_set.get_span_contents(tokens[idx].span).to_vec();
186	if key_bytes.first().copied() == Some(b',') {
187	idx += 1;
188	continue;
189	}
190	
191	let Some(key) =
192	parse_value(working_set, tokens[idx].span, &SyntaxShape::String).as_string()
193	else {
194	working_set.error(key_error(tokens[idx].span));
195	return mk_shape(vec![]);
196	};
197	
198	// we want to allow such an annotation
199	// `record<name>` where the user leaves out the type
200	if idx + 1 == tokens.len() {
201	sig.push((key, SyntaxShape::Any));
202	break;
203	} else {
204	idx += 1;
205	}
206	
207	let maybe_colon = working_set.get_span_contents(tokens[idx].span).to_vec();
208	match maybe_colon.as_slice() {
209	b":" => {
210	if idx + 1 == tokens.len() {
211	working_set
212	.error(ParseError::Expected("type after colon", tokens[idx].span));
213	break;
214	} else {
215	idx += 1;
216	}
217	}
218	// a key provided without a type
219	b"," => {
220	idx += 1;
221	sig.push((key, SyntaxShape::Any));
222	continue;
223	}
224	// a key provided without a type
225	_ => {
226	sig.push((key, SyntaxShape::Any));
227	continue;
228	}
229	}
230	
231	let shape_bytes = working_set.get_span_contents(tokens[idx].span).to_vec();
232	let shape = parse_shape_name(working_set, &shape_bytes, tokens[idx].span, use_loc);
233	sig.push((key, shape));
234	idx += 1;
235	}
236	
237	mk_shape(sig)
238	} else {
239	working_set.error(ParseError::UnknownType(span));
240	
241	SyntaxShape::Any
242	}
243	}
