245	fn parse_list_shape(
246	working_set: &mut StateWorkingSet,
247	bytes: &[u8],
248	span: Span,
249	use_loc: ShapeDescriptorUse,
250	) -> SyntaxShape {
251	assert!(bytes.starts_with(b"list"));
252	
253	if bytes == b"list" {
254	SyntaxShape::List(Box::new(SyntaxShape::Any))
255	} else if bytes.starts_with(b"list<") {
256	let Some(inner_span) = prepare_inner_span(working_set, bytes, span, 5) else {
257	return SyntaxShape::Any;
258	};
259	
260	let inner_text = String::from_utf8_lossy(working_set.get_span_contents(inner_span));
261	// remove any extra whitespace, for example `list< string >` becomes `list<string>`
262	let inner_bytes = inner_text.trim().as_bytes().to_vec();
263	
264	// list<>
265	if inner_bytes.is_empty() {
266	SyntaxShape::List(Box::new(SyntaxShape::Any))
267	} else {
268	let inner_sig = parse_shape_name(working_set, &inner_bytes, inner_span, use_loc);
269	
270	SyntaxShape::List(Box::new(inner_sig))
271	}
272	} else {
273	working_set.error(ParseError::UnknownType(span));
274	
275	SyntaxShape::List(Box::new(SyntaxShape::Any))
276	}
277	}
