279	fn prepare_inner_span(
280	working_set: &mut StateWorkingSet,
281	bytes: &[u8],
282	span: Span,
283	prefix_len: usize,
284	) -> Option<Span> {
285	let start = span.start + prefix_len;
286	
287	if bytes.ends_with(b">") {
288	let end = span.end - 1;
289	Some(Span::new(start, end))
290	} else if bytes.contains(&b'>') {
291	let angle_start = bytes.split(|it| it == &b'>').collect::<Vec<_>>()[0].len() + 1;
292	let span = Span::new(span.start + angle_start, span.end);
293	
294	working_set.error(ParseError::LabeledError(
295	"Extra characters in the parameter name".into(),
296	"extra characters".into(),
297	span,
298	));
299	
300	None
301	} else {
302	working_set.error(ParseError::Unclosed(">".into(), span));
303	None
304	}
305	}
