62	#[allow(clippy::cognitive_complexity)]
63	fn get_documentation(
64	    sig: &Signature,
65	    examples: &[Example],
66	    engine_state: &EngineState,
67	    stack: &mut Stack,
68	    config: &DocumentationConfig,
69	    is_parser_keyword: bool,
70	) -> String {
71	    // Create ansi colors
72	    //todo make these configurable -- pull from enginestate.config
73	    let help_section_name: String =
74	        get_ansi_color_for_component_or_default(engine_state, "shape_string", "\x1b[32m"); // default: green
75	
76	    let help_subcolor_one: String =
77	        get_ansi_color_for_component_or_default(engine_state, "shape_external", "\x1b[36m"); // default: cyan
78	                                                                                             // was const bb: &str = "\x1b[1;34m"; // bold blue
79	    let help_subcolor_two: String =
80	        get_ansi_color_for_component_or_default(engine_state, "shape_block", "\x1b[94m"); // default: light blue (nobold, should be bolding the *names*)
81	
82	    const RESET: &str = "\x1b[0m"; // reset
83	
84	    let cmd_name = &sig.name;
85	    let mut long_desc = String::new();
86	
87	    let usage = &sig.usage;
88	    if !usage.is_empty() {
89	        long_desc.push_str(usage);
90	        long_desc.push_str("\n\n");
91	    }
92	
93	    let extra_usage = if config.brief { "" } else { &sig.extra_usage };
94	    if !extra_usage.is_empty() {
95	        long_desc.push_str(extra_usage);
96	        long_desc.push_str("\n\n");
97	    }
98	
99	    let mut subcommands = vec![];
100	    if !config.no_subcommands {
101	        let signatures = engine_state.get_signatures(true);
102	        for sig in signatures {
103	            if sig.name.starts_with(&format!("{cmd_name} "))
104	                // Don't display removed/deprecated commands in the Subcommands list
105	                    && !matches!(sig.category, Category::Removed)
106	            {
107	                subcommands.push(format!(
108	                    "  {help_subcolor_one}{}{RESET} - {}",
109	                    sig.name, sig.usage
110	                ));
111	            }
112	        }
113	    }
114	
115	    if !sig.search_terms.is_empty() {
116	        let text = format!(
117	            "{help_section_name}Search terms{RESET}: {help_subcolor_one}{}{}\n\n",
118	            sig.search_terms.join(", "),
119	            RESET
120	        );
121	        let _ = write!(long_desc, "{text}");
122	    }
123	
124	    let text = format!(
125	        "{}Usage{}:\n  > {}\n",
126	        help_section_name,
127	        RESET,
128	        sig.call_signature()
129	    );
130	    let _ = write!(long_desc, "{text}");
131	
132	    if !subcommands.is_empty() {
133	        let _ = write!(long_desc, "\n{help_section_name}Subcommands{RESET}:\n");
134	        subcommands.sort();
135	        long_desc.push_str(&subcommands.join("\n"));
136	        long_desc.push('\n');
137	    }
138	
139	    if !sig.named.is_empty() {
140	        long_desc.push_str(&get_flags_section(Some(engine_state), sig, |v| {
141	            nu_highlight_string(
142	                &v.into_string_parsable(", ", &engine_state.config),
143	                engine_state,
144	                stack,
145	            )
146	        }))
147	    }
148	
149	    if !sig.required_positional.is_empty()
150	        || !sig.optional_positional.is_empty()
151	        || sig.rest_positional.is_some()
152	    {
153	        let _ = write!(long_desc, "\n{help_section_name}Parameters{RESET}:\n");
154	        for positional in &sig.required_positional {
155	            let text = match &positional.shape {
156	                SyntaxShape::Keyword(kw, shape) => {
157	                    format!(
158	                        "  {help_subcolor_one}\"{}\" + {RESET}<{help_subcolor_two}{}{RESET}>: {}",
159	                        String::from_utf8_lossy(kw),
160	                        document_shape(*shape.clone()),
161	                        positional.desc
162	                    )
163	                }
164	                _ => {
165	                    format!(
166	                        "  {help_subcolor_one}{}{RESET} <{help_subcolor_two}{}{RESET}>: {}",
167	                        positional.name,
168	                        document_shape(positional.shape.clone()),
169	                        positional.desc
170	                    )
171	                }
172	            };
173	            let _ = writeln!(long_desc, "{text}");
174	        }
175	        for positional in &sig.optional_positional {
176	            let text = match &positional.shape {
177	                SyntaxShape::Keyword(kw, shape) => {
178	                    format!(
179	                        "  {help_subcolor_one}\"{}\" + {RESET}<{help_subcolor_two}{}{RESET}>: {} (optional)",
180	                        String::from_utf8_lossy(kw),
181	                        document_shape(*shape.clone()),
182	                        positional.desc
183	                    )
184	                }
185	                _ => {
186	                    let opt_suffix = if let Some(value) = &positional.default_value {
187	                        format!(
188	                            " (optional, default: {})",
189	                            nu_highlight_string(
190	                                &value.into_string_parsable(", ", &engine_state.config),
191	                                engine_state,
192	                                stack
193	                            )
194	                        )
195	                    } else {
196	                        (" (optional)").to_string()
197	                    };
198	
199	                    format!(
200	                        "  {help_subcolor_one}{}{RESET} <{help_subcolor_two}{}{RESET}>: {}{}",
201	                        positional.name,
202	                        document_shape(positional.shape.clone()),
203	                        positional.desc,
204	                        opt_suffix,
205	                    )
206	                }
207	            };
208	            let _ = writeln!(long_desc, "{text}");
209	        }
210	
211	        if let Some(rest_positional) = &sig.rest_positional {
212	            let text = format!(
213	                "  ...{help_subcolor_one}{}{RESET} <{help_subcolor_two}{}{RESET}>: {}",
214	                rest_positional.name,
215	                document_shape(rest_positional.shape.clone()),
216	                rest_positional.desc
217	            );
218	            let _ = writeln!(long_desc, "{text}");
219	        }
220	    }
221	
222	    if !is_parser_keyword && !sig.input_output_types.is_empty() {
223	        if let Some(decl_id) = engine_state.find_decl(b"table", &[]) {
224	            // FIXME: we may want to make this the span of the help command in the future
225	            let span = Span::unknown();
226	            let mut vals = vec![];
227	            for (input, output) in &sig.input_output_types {
228	                vals.push(Value::record(
