230	                        "input" => Value::string(input.to_string(), span),
231	                        "output" => Value::string(output.to_string(), span),
232	                    },
233	                    span,
234	                ));
235	            }
236	
237	            let mut caller_stack = Stack::new();
238	            if let Ok(result) = eval_call(
239	                engine_state,
240	                &mut caller_stack,
241	                &Call {
242	                    decl_id,
243	                    head: span,
244	                    arguments: vec![],
245	                    redirect_stdout: true,
246	                    redirect_stderr: true,
247	                    parser_info: HashMap::new(),
248	                },
249	                PipelineData::Value(Value::list(vals, span), None),
250	            ) {
251	                if let Ok((str, ..)) = result.collect_string_strict(span) {
252	                    let _ = writeln!(long_desc, "\n{help_section_name}Input/output types{RESET}:");
253	                    for line in str.lines() {
