255	                    }
256	                }
257	            }
258	        }
259	    }
260	
261	    if !examples.is_empty() {
262	        let _ = write!(long_desc, "\n{help_section_name}Examples{RESET}:");
263	    }
264	
265	    for example in examples {
266	        long_desc.push('\n');
267	        long_desc.push_str("  ");
268	        long_desc.push_str(example.description);
269	
270	        if config.no_color {
271	            let _ = write!(long_desc, "\n  > {}\n", example.example);
272	        } else if let Some(highlighter) = engine_state.find_decl(b"nu-highlight", &[]) {
273	            let decl = engine_state.get_decl(highlighter);
274	
275	            match decl.run(
276	                engine_state,
277	                stack,
278	                &Call::new(Span::unknown()),
279	                Value::string(example.example, Span::unknown()).into_pipeline_data(),
280	            ) {
281	                Ok(output) => {
282	                    let result = output.into_value(Span::unknown());
283	                    match result.as_string() {
284	                        Ok(s) => {
285	                            let _ = write!(long_desc, "\n  > {s}\n");
286	                        }
287	                        _ => {
288	                            let _ = write!(long_desc, "\n  > {}\n", example.example);
289	                        }
290	                    }
291	                }
292	                Err(_) => {
293	                    let _ = write!(long_desc, "\n  > {}\n", example.example);
294	                }
295	            }
296	        } else {
297	            let _ = write!(long_desc, "\n  > {}\n", example.example);
298	        }
299	
300	        if let Some(result) = &example.result {
301	            let table = engine_state
302	                .find_decl("table".as_bytes(), &[])
303	                .and_then(|decl_id| {
304	                    engine_state
305	                        .get_decl(decl_id)
306	                        .run(
307	                            engine_state,
308	                            stack,
309	                            &Call::new(Span::new(0, 0)),
310	                            PipelineData::Value(result.clone(), None),
