319	                    item.into_string("", engine_state.get_config())
320	                        .replace('\n', "\n  ")
321	                        .trim()
322	                );
323	            }
324	        }
325	    }
326	
327	    long_desc.push('\n');
328	
329	    if config.no_color {
330	        nu_utils::strip_ansi_string_likely(long_desc)
331	    } else {
332	        long_desc
333	    }
334	}
