336	fn get_ansi_color_for_component_or_default(
337	    engine_state: &EngineState,
338	    theme_component: &str,
339	    default: &str,
340	) -> String {
341	    if let Some(color) = &engine_state.get_config().color_config.get(theme_component) {
342	        let mut caller_stack = Stack::new();
343	        let span = Span::unknown();
344	
345	        let argument_opt = get_argument_for_color_value(engine_state, color, span);
346	
347	        // Call ansi command using argument
348	        if let Some(argument) = argument_opt {
349	            if let Some(decl_id) = engine_state.find_decl(b"ansi", &[]) {
350	                if let Ok(result) = eval_call(
351	                    engine_state,
352	                    &mut caller_stack,
353	                    &Call {
354	                        decl_id,
355	                        head: span,
356	                        arguments: vec![argument],
357	                        redirect_stdout: true,
358	                        redirect_stderr: true,
359	                        parser_info: HashMap::new(),
360	                    },
361	                    PipelineData::Empty,
362	                ) {
363	                    if let Ok((str, ..)) = result.collect_string_strict(span) {
364	                        return str;
365	                    }
366	                }
367	            }
368	        }
369	    }
370	
371	    default.to_string()
372	}
