374	fn get_argument_for_color_value(
375	    engine_state: &EngineState,
376	    color: &&Value,
377	    span: Span,
378	) -> Option<Argument> {
379	    match color {
380	        Value::Record { val, .. } => {
381	            let record_exp: Vec<RecordItem> = val
382	                .into_iter()
