384	                    RecordItem::Pair(
385	                        Expression {
386	                            expr: Expr::String(k.clone()),
387	                            span,
388	                            ty: Type::String,
389	                            custom_completion: None,
390	                        },
391	                        Expression {
392	                            expr: Expr::String(
393	                                v.clone().into_string("", engine_state.get_config()),
394	                            ),
395	                            span,
396	                            ty: Type::String,
397	                            custom_completion: None,
398	                        },
399	                    )
400	                })
401	                .collect();
402	
403	            Some(Argument::Positional(Expression {
404	                span: Span::unknown(),
405	                ty: Type::Record(vec![
406	                    ("fg".to_string(), Type::String),
407	                    ("attr".to_string(), Type::String),
408	                ]),
409	                expr: Expr::Record(record_exp),
410	                custom_completion: None,
411	            }))
412	        }
413	        Value::String { val, .. } => Some(Argument::Positional(Expression {
414	            span: Span::unknown(),
415	            ty: Type::String,
416	            expr: Expr::String(val.clone()),
417	            custom_completion: None,
418	        })),
419	        _ => None,
420	    }
421	}
