212	    /// Returns a slice of self for the provided range.
213	    ///
214	    /// This will increment the reference count for the underlying memory and
215	    /// return a new `Bytes` handle set to the slice.
216	    ///
217	    /// This operation is `O(1)`.
218	    ///
219	    /// # Examples
220	    ///
221	    /// ```
222	    /// use bytes::Bytes;
223	    ///
224	    /// let a = Bytes::from(&b"hello world"[..]);
225	    /// let b = a.slice(2..5);
226	    ///
227	    /// assert_eq!(&b[..], b"llo");
228	    /// ```
