230	    /// # Panics
231	    ///
232	    /// Requires that `begin <= end` and `end <= self.len()`, otherwise slicing
233	    /// will panic.
234	    pub fn slice(&self, range: impl RangeBounds<usize>) -> Bytes {
235	        use core::ops::Bound;
236	
237	        let len = self.len();
238	
239	        let begin = match range.start_bound() {
240	            Bound::Included(&n) => n,
241	            Bound::Excluded(&n) => n + 1,
242	            Bound::Unbounded => 0,
243	        };
244	
245	        let end = match range.end_bound() {
246	            Bound::Included(&n) => n.checked_add(1).expect("out of range"),
247	            Bound::Excluded(&n) => n,
248	            Bound::Unbounded => len,
249	        };
250	
251	        assert!(
252	            begin <= end,
253	            "range start must not be greater than end: {:?} <= {:?}",
254	            begin,
255	            end,
256	        );
257	        assert!(
258	            end <= len,
259	            "range end out of bounds: {:?} <= {:?}",
260	            end,
261	            len,
262	        );
263	
264	        if end == begin {
265	            return Bytes::new();
266	        }
267	
268	        let mut ret = self.clone();
269	
270	        ret.len = end - begin;
271	        ret.ptr = unsafe { ret.ptr.add(begin) };
272	
273	        ret
274	    }
