276	    /// Returns a slice of self that is equivalent to the given `subset`.
277	    ///
278	    /// When processing a `Bytes` buffer with other tools, one often gets a
279	    /// `&[u8]` which is in fact a slice of the `Bytes`, i.e. a subset of it.
280	    /// This function turns that `&[u8]` into another `Bytes`, as if one had
281	    /// called `self.slice()` with the offsets that correspond to `subset`.
282	    ///
283	    /// This operation is `O(1)`.
284	    ///
285	    /// # Examples
286	    ///
287	    /// ```
288	    /// use bytes::Bytes;
289	    ///
290	    /// let bytes = Bytes::from(&b"012345678"[..]);
291	    /// let as_slice = bytes.as_ref();
292	    /// let subset = &as_slice[2..6];
293	    /// let subslice = bytes.slice_ref(&subset);
294	    /// assert_eq!(&subslice[..], b"2345");
295	    /// ```
296	    ///
297	    /// # Panics
298	    ///
299	    /// Requires that the given `sub` slice is in fact contained within the
300	    /// `Bytes` buffer; otherwise this function will panic.
301	    pub fn slice_ref(&self, subset: &[u8]) -> Bytes {
302	        // Empty slice and empty Bytes may have their pointers reset
303	        // so explicitly allow empty slice to be a subslice of any slice.
304	        if subset.is_empty() {
305	            return Bytes::new();
306	        }
307	
308	        let bytes_p = self.as_ptr() as usize;
309	        let bytes_len = self.len();
310	
311	        let sub_p = subset.as_ptr() as usize;
312	        let sub_len = subset.len();
313	
314	        assert!(
315	            sub_p >= bytes_p,
316	            "subset pointer ({:p}) is smaller than self pointer ({:p})",
317	            subset.as_ptr(),
318	            self.as_ptr(),
319	        );
320	        assert!(
321	            sub_p + sub_len <= bytes_p + bytes_len,
322	            "subset is out of bounds: self = ({:p}, {}), subset = ({:p}, {})",
323	            self.as_ptr(),
324	            bytes_len,
325	            subset.as_ptr(),
326	            sub_len,
327	        );
328	
329	        let sub_offset = sub_p - bytes_p;
330	
331	        self.slice(sub_offset..(sub_offset + sub_len))
332	    }
