104	/// The generated span's name will be the name of the function. Any arguments
105	/// to that function will be recorded as fields using [`fmt::Debug`]. To skip
106	/// recording a function's or method's argument, pass the argument's name
107	/// to the `skip` argument on the `#[instrument]` macro. For example,
108	/// `skip` can be used when an argument to an instrumented function does
109	/// not implement [`fmt::Debug`], or to exclude an argument with a verbose
110	/// or costly Debug implementation. Note that:
111	/// - multiple argument names can be passed to `skip`.
112	/// - arguments passed to `skip` do _not_ need to implement `fmt::Debug`.
113	///
114	/// You can also pass additional fields (key-value pairs with arbitrary data)
115	/// to the generated span. This is achieved using the `fields` argument on the
116	/// `#[instrument]` macro. You can use a string, integer or boolean literal as
117	/// a value for each field. The name of the field must be a single valid Rust
118	/// identifier, nested (dotted) field names are not supported.
119	///
120	/// Note that overlap between the names of fields and (non-skipped) arguments
121	/// will result in a compile error.
122	///
123	/// # Examples
124	/// Instrumenting a function:
125	/// ```
126	/// # use tracing_attributes::instrument;
127	/// #[instrument]
128	/// pub fn my_function(my_arg: usize) {
129	///     // This event will be recorded inside a span named `my_function` with the
130	///     // field `my_arg`.
131	///     tracing::info!("inside my_function!");
132	///     // ...
133	/// }
134	/// ```
135	/// Setting the level for the generated span:
136	/// ```
137	/// # use tracing_attributes::instrument;
138	/// #[instrument(level = "debug")]
139	/// pub fn my_function() {
140	///     // ...
141	/// }
142	/// ```
143	/// Overriding the generated span's name:
144	/// ```
145	/// # use tracing_attributes::instrument;
146	/// #[instrument(name = "my_name")]
147	/// pub fn my_function() {
148	///     // ...
149	/// }
150	/// ```
151	/// Overriding the generated span's target:
152	/// ```
153	/// # use tracing_attributes::instrument;
154	/// #[instrument(target = "my_target")]
155	/// pub fn my_function() {
156	///     // ...
157	/// }
158	/// ```
159	///
160	/// To skip recording an argument, pass the argument's name to the `skip`:
161	///
162	/// ```
163	/// # use tracing_attributes::instrument;
164	/// struct NonDebug;
165	///
166	/// #[instrument(skip(non_debug))]
167	/// fn my_function(arg: usize, non_debug: NonDebug) {
168	///     // ...
169	/// }
170	/// ```
171	///
172	/// To add an additional context to the span, you can pass key-value pairs to `fields`:
173	///
174	/// ```
175	/// # use tracing_attributes::instrument;
176	/// #[instrument(fields(foo="bar", id=1, show=true))]
177	/// fn my_function(arg: usize) {
178	///     // ...
179	/// }
180	/// ```
181	///
182	/// If the function returns a `Result<T, E>` and `E` implements `std::fmt::Display`, you can add
183	/// `err` to emit error events when the function returns `Err`:
